<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/app/common.php';$pdo=db();
// Test campaigns are simulated and can never reach the phone.
$jobs=$pdo->query("SELECT j.id,j.campaign_id FROM sms_jobs j JOIN campaigns c ON c.id=j.campaign_id WHERE j.status='queued' AND c.test_mode=1 LIMIT 200")->fetchAll();foreach($jobs as $j){$pdo->prepare("UPDATE sms_jobs SET status='sent',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='queued'")->execute([$j['id']]);$pdo->prepare("INSERT INTO sms_events(job_id,event_type,detail,created_at) VALUES(?,'sent','Test mode simulation',CURRENT_TIMESTAMP)")->execute([$j['id']]);}$pdo->prepare('DELETE FROM api_rate_limits WHERE window_start < ?')->execute([gmdate('Y-m-d H:i:s',time()-86400)]);$pdo->prepare("UPDATE gateways SET status='offline' WHERE last_seen < ? AND status='online'")->execute([gmdate('Y-m-d H:i:s',time()-180)]);$pdo->exec("UPDATE campaigns SET status='completed',ended_at=CURRENT_TIMESTAMP WHERE status IN ('queued','running') AND NOT EXISTS (SELECT 1 FROM sms_jobs WHERE campaign_id=campaigns.id AND status IN ('queued','processing'))");echo 'simulated='.count($jobs).PHP_EOL;
